#include "fixes/custom_map_asset_isolation/SpeechContentLease.h"
#include <cstdio>
#include <cstring>
namespace lease=dluma::fixes::custom_map_asset_isolation::speech_content_lease;
namespace {
#define CHECK(x) do{if(!(x)){std::printf("FAIL %d: %s error=%lu\n",__LINE__,#x,GetLastError());return false;}}while(0)
struct NativeFile {std::uintptr_t vtable=0x2003F908;std::uintptr_t name=0,length=0,source=0;HANDLE handle=nullptr;};
bool Read(void* user,std::uintptr_t address,void* output,std::size_t size)noexcept{
 const auto begin=reinterpret_cast<std::uintptr_t>(user);if(address<begin||size>sizeof(NativeFile)||address-begin>sizeof(NativeFile)-size)return false;std::memcpy(output,reinterpret_cast<void*>(address),size);return true;}
lease::NaturalOpen Scope(const char* path,NativeFile& f){lease::NaturalOpen o={};o.engine_base=0x10000000;o.filesystem_base=0x20000000;o.native_file=reinterpret_cast<std::uintptr_t>(&f);o.caller_return=0x1032A8F8;o.speech_scope_generation=1;o.provider_identity=9;o.provider_generation=3;o.owner_thread_id=GetCurrentThreadId();o.exact_player_images=true;std::strcpy(o.resolved_path,path);return o;}
bool Finish(lease::ReadJob& j){for(unsigned i=0;i<1000&&j.state==lease::State::Reading;++i)lease::Step(&j);return j.state==lease::State::Hashed;}
bool WriterDenied(const char* path){HANDLE h=CreateFileA(path,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);if(h!=INVALID_HANDLE_VALUE){CloseHandle(h);return false;}return GetLastError()==32;}
bool HistoricalPinSurvivesClose(const char* path){NativeFile f;f.handle=CreateFileA(path,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);CHECK(f.handle!=INVALID_HANDLE_VALUE);lease::Pin p={};CHECK(lease::CaptureNaturalPin(&p,Scope(path,f),Read,&f));CHECK(CloseHandle(f.handle));CHECK(WriterDenied(path));lease::ReadJob job={};CHECK(lease::BeginRead(&job,p,1<<20));CHECK(Finish(job));CHECK(lease::CloseRead(&job));CHECK(WriterDenied(path));CHECK(lease::ReleasePin(&p));HANDLE write=CreateFileA(path,GENERIC_WRITE,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);CHECK(write!=INVALID_HANDLE_VALUE);CloseHandle(write);return true;}
bool IndependentPosition(const char* path){NativeFile f;f.handle=CreateFileA(path,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);CHECK(f.handle!=INVALID_HANDLE_VALUE);char bytes[5];DWORD got=0;CHECK(ReadFile(f.handle,bytes,5,&got,nullptr)&&got==5);lease::Pin p={};CHECK(lease::CaptureNaturalPin(&p,Scope(path,f),Read,&f));lease::ReadJob j={};CHECK(lease::BeginRead(&j,p,1<<20));CHECK(Finish(j));char next=0;CHECK(ReadFile(f.handle,&next,1,&got,nullptr)&&got==1&&next=='5');CHECK(lease::CloseRead(&j));CHECK(lease::ReleasePin(&p));CloseHandle(f.handle);return true;}
bool ReplayVerifiedBeforePublication(const char* path){lease::Pin p={};CHECK(lease::OpenReplayPin(&p,path,9,3,2));lease::ReadJob j={};CHECK(lease::BeginRead(&j,p,1<<20));CHECK(!lease::ReadyForNativeSpeechLoad(j,p));CHECK(Finish(j));unsigned char hash[32];std::memcpy(hash,j.sha256,32);CHECK(!lease::ReadyForNativeSpeechLoad(j,p));CHECK(lease::VerifyExpected(&j,hash));CHECK(lease::ReadyForNativeSpeechLoad(j,p));CHECK(WriterDenied(path));CHECK(lease::CloseRead(&j));CHECK(!lease::ReadyForNativeSpeechLoad(j,p));CHECK(lease::ReleasePin(&p));return true;}
bool WrongContentNeverReady(const char* path){lease::Pin p={};CHECK(lease::OpenReplayPin(&p,path,9,3,2));lease::ReadJob j={};CHECK(lease::BeginRead(&j,p,1<<20));CHECK(Finish(j));unsigned char hash[32];std::memcpy(hash,j.sha256,32);hash[0]^=1;CHECK(!lease::VerifyExpected(&j,hash));CHECK(!lease::ReadyForNativeSpeechLoad(j,p));CHECK(j.failure==lease::Failure::ContentMismatch);lease::CloseRead(&j);lease::ReleasePin(&p);return true;}
bool SizeLimitAndCleanup(const char* path){lease::Pin p={};CHECK(lease::OpenReplayPin(&p,path,9,3,2));lease::ReadJob j={};CHECK(!lease::BeginRead(&j,p,1));CHECK(!j.reader&&j.failure==lease::Failure::InvalidSize);lease::CloseRead(&j);CHECK(lease::ReleasePin(&p));return true;}
bool WrongNativeScopeAndLastError(const char* path){NativeFile f;f.handle=CreateFileA(path,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);CHECK(f.handle!=INVALID_HANDLE_VALUE);lease::Pin p={};auto o=Scope(path,f);o.caller_return++;CHECK(!lease::CaptureNaturalPin(&p,o,Read,&f));CHECK(!p.handle);p={};SetLastError(1234);CHECK(lease::CaptureNaturalPin(&p,Scope(path,f),Read,&f));CHECK(GetLastError()==1234);lease::ReleasePin(&p);p={};f.vtable++;CHECK(!lease::CaptureNaturalPin(&p,Scope(path,f),Read,&f));CHECK(!p.handle);CloseHandle(f.handle);return true;}
bool OwnershipAndProviderGeneration(const char* path){lease::Pin original={},p={};CHECK(lease::OpenReplayPin(&original,path,9,3,2));CHECK(lease::TransferPin(&original,&p));CHECK(!original.handle&&original.state==lease::State::Closed);CHECK(!lease::TransferPin(&original,&p));lease::ReadJob j={};CHECK(lease::BeginRead(&j,p,1<<20));CHECK(Finish(j));CHECK(lease::VerifyExpected(&j,j.sha256));CHECK(lease::ReadyForNativeSpeechLoad(j,p));++p.provider_generation;CHECK(!lease::ReadyForNativeSpeechLoad(j,p));lease::CloseRead(&j);lease::ReleasePin(&p);return true;}
bool IdentityRejectsOtherFile(const char* path,const char* other){lease::Pin p={};CHECK(lease::OpenReplayPin(&p,path,9,3,2));std::strcpy(p.path,other);lease::ReadJob j={};CHECK(!lease::BeginRead(&j,p,1<<20));CHECK(j.failure==lease::Failure::IdentityMismatch);lease::CloseRead(&j);lease::ReleasePin(&p);return true;}
}
int main(int argc,char** argv){if(argc!=3)return 2;bool(*tests[])(const char*)={HistoricalPinSurvivesClose,IndependentPosition,ReplayVerifiedBeforePublication,WrongContentNeverReady,SizeLimitAndCleanup,WrongNativeScopeAndLastError,OwnershipAndProviderGeneration};for(unsigned i=0;i<sizeof(tests)/sizeof(tests[0]);++i){if(!tests[i](argv[1]))return 1;std::printf("PASS speech_lease_%u\n",i);}if(!IdentityRejectsOtherFile(argv[1],argv[2]))return 1;std::puts("PASS identity");return 0;}
